cd /office && python3 - <<'PY'
import csv, re, json

# ---- capacity increments effective <= day9 ----
inc = {}  # station -> total
base = {'东港':8,'西湾':9,'南站':7,'北仓':8}
inc.update(base)
# day6 东港+3, day7 南站+3, day9 北仓+2
inc['东港'] += 3
inc['南站'] += 3
inc['北仓'] += 2
print("容量(<=9):", inc)

# ---- prior ACTUAL deliveries with reserved seats + status ----
# (case, station, reserved, status)  status: 待确认/已确认 occupy; 退信 released; 未发 not delivered
prior = [
 ('P01','南站',6,'待确认'),('P02','南站',0,'已确认'),('P03','东港',0,'退信'),
 ('P04','西湾',4,'已确认'),('P05','西湾',3,'已确认'),('P06','北仓',3,'已确认'),
 ('P07','东港',6,'已确认'),('P09','南站',0,'退信'),('P10','北仓',3,'已确认'),
 ('P11','北仓',0,'已确认'),
 # R4 补办 all 0
 ('L01-R','南站',0,'补办'),('L02-R','南站',0,'补办'),('P03-R','东港',0,'补办'),('P09-R','南站',0,'补办'),
 # R6 网点
 ('N01','西湾',0,'已发'),('N02','东港',5,'已发'),('N03','南站',0,'已发'),('N04','西湾',0,'已发'),
]
occ = {s:0 for s in inc}
for c,st,r,status in prior:
    if status in ('退信','未发'):  # released / not delivered
        continue
    occ[st]+=r
print("结转占用:", occ)
rem = {s: inc[s]-occ[s] for s in inc}
print("真实结转余量:", rem)

# ---- parse 06-09 设备申请 ----
rows=[]
with open('inbox/06-09/设备申请.csv',encoding='utf-8-sig') as f:
    for row in csv.DictReader(f):
        rows.append(row)
# demand per case: per 设备序号 take max 修订号; if that row 取消 -> 0 else sum 申请席位
from collections import defaultdict
dev = defaultdict(dict)  # case -> dev -> (rev, 状态, 席位)
info = {}
for row in rows:
    case=row['案号']; d=row['设备序号']; rev=int(row['修订号']); seats=int(row['申请席位']); st=row['状态']
    info[case]=(row['优先号'],row['服务类别'])
    if d not in dev[case] or rev>dev[case][d][0]:
        dev[case][d]=(rev,st,seats)
demand={}
for case,dd in dev.items():
    tot=0
    parts=[]
    for d,(rev,st,seats) in dd.items():
        if st=='取消':
            parts.append((d,rev,'取消',0))
        else:
            tot+=seats; parts.append((d,rev,st,seats))
    demand[case]=tot
    print(case,"devices:",parts,"=> demand",tot)

# ---- allocate by priority asc ----
order=sorted(info.items(), key=lambda kv:(int(kv[1][0]), kv[0]))
print("\nallocation order:",[(c,v[0]) for c,v in order])
station={'T01':'南站','T02':'西湾','T03':'南站'}
voucher={'T01':'S32','T02':'S21','T03':'S31'}
term={'T01':'7个工作日','T02':'5个工作日','T03':'10个工作日'}
obj={'T01':'HZ-A','T02':'JL-B','T03':'QH-A'}
res={}
for case,(pri,cat) in order:
    st=station[case]; d=demand[case]
    if rem[st]>=d:
        res[case]=d; rem[st]-=d
    else:
        res[case]=0
    print(f"{case} pri{pri} {st} demand{d} -> reserved {res[case]} | 余 {rem[st]}")
print("\nFINAL:")
for c in ['T01','T02','T03']:
    print(c, obj[c], term[c], station[c], voucher[c], res[c])
PY

